solution.javascript:
function titleCase(sentence) {
  const words = sentence.split(' ')
  for (let i = 0; i < words.length; i++) {
    const word = words[i]
    if (word.length > 0) {
      words[i] = word[0].toUpperCase() + word.slice(1).toLowerCase()
    }
  }
  return words.join(' ')
}
